  "overall_summary": "The candidate's answer is extremely vague, lacking a concrete feature design, explicit user segmentation, success metrics, and structured problem framing.",
  "strengths": [
    "Recognizes the importance of talking to customers to understand their business problems."
  ],
  "weaknesses": [
    {
      "tag": "no_clear_problem_framing",
      "evidence": "The candidate immediately talks about talking to the client without defining the core problem, goal, or scope of food waste reduction in the B2B inventory tool.",
      "fix": "Spend the first minute defining the problem. Ask about the goal, the type of customer, and any constraints, or state your assumptions out loud if the interviewer does not answer. For example: 'Before designing this, I want to confirm: are we trying to reduce inventory spoilage or prep-waste, and are we focused on independent restaurants or large chains?'"
    }
  ],
  "next_steps": [
    "Practice structured product design frameworks that explicitly outline target user segments.",
    "Define concrete success metrics and KPIs for any proposed feature.",
    "Incorporate risk analysis and tradeoffs into solution evaluations."
  ]
}

